using System;

// PROGRAM: Eksperimen Generic Constraints dan Covariance
public interface IIdentifiable
{
    string Id { get; }
}

public record CustomerDto(string Id, string Name) : IIdentifiable;

// Generic Class dengan Constraint: T wajib class dan mengimplementasikan IIdentifiable
public class CacheStorage<T> where T : class, IIdentifiable
{
    private T? _cachedItem;

    public void Store(T item)
    {
        _cachedItem = item;
        Console.WriteLine($"[CACHE] Menyimpan item ID: {item.Id}");
    }

    public T? Retrieve() => _cachedItem;
}

// Covariant Interface (out T)
public interface IProducer<out T>
{
    T Produce();
}

public class StringProducer : IProducer<string>
{
    public string Produce() => "Halo dari Covariant Producer!";
}

public class Program
{
    public static void Main()
    {
        var cache = new CacheStorage<CustomerDto>();
        cache.Store(new CustomerDto("CUST-001", "Budi Santoso"));

        // Bukti Covariance: IProducer<string> aman ditugaskan ke IProducer<object>
        IProducer<object> objProducer = new StringProducer();
        Console.WriteLine($"Output: {objProducer.Produce()}");
    }
}

