using System;

public interface IIdentifiable
{
    string Id { get; }
}

public record Account(string Id, decimal Saldo) : IIdentifiable;

public class RepositoryHelper
{
    public static T? FindById<T>(T[] items, string id) where T : class, IIdentifiable
    {
        if (items == null || string.IsNullOrWhiteSpace(id)) return null;

        foreach (var item in items)
        {
            if (item != null && string.Equals(item.Id, id, StringComparison.OrdinalIgnoreCase))
            {
                return item;
            }
        }

        return null;
    }

    public static void Main()
    {
        Account[] accounts = { new("ACC-1", 1000m), new("ACC-2", 5000m) };
        var found = FindById(accounts, "ACC-2");
        Console.WriteLine($"Found: {found?.Id} Saldo: {found?.Saldo}");
    }
}
